using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using System.IO;using System.Linq;
[InitializeOnLoad]public static class GangfireBuild{static GangfireBuild(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("Gangfire.request"))return;File.Delete("Gangfire.request");var objs=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name=="building11 (1)"||t.name=="Gangfire Weapon Shop").ToArray();File.WriteAllText("FinalEnvironmentRoadReview/GangfireAudit.txt",string.Join("\n",objs.Select(t=>t.name+" pos="+t.position+" rot="+t.eulerAngles+" active="+t.gameObject.activeInHierarchy+" scale="+t.lossyScale+"\n"+string.Join("\n",t.GetComponentsInChildren<Renderer>(true).Select(r=>r.name+" bounds="+r.bounds+" enabled="+r.enabled+" active="+r.gameObject.activeInHierarchy+" mesh="+(r.GetComponent<MeshFilter>()?r.GetComponent<MeshFilter>().sharedMesh.bounds.ToString():"none")+" invalid="+(r.GetComponent<MeshFilter>()?r.GetComponent<MeshFilter>().sharedMesh.vertices.Count(p=>float.IsNaN(p.x)||float.IsInfinity(p.x)||float.IsNaN(p.y)||float.IsNaN(p.z)):0))))));}}

